-- 4. Row-level security on EVERY table. Student tables already force it (owner rows only).
--    Account and sign-in tables: only the auth login, through an explicit policy.
--    Django's own bookkeeping tables: no policy, so no other login can read them.
ALTER TABLE public.accounts_accounttoken ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS ucc_auth_access ON public.accounts_accounttoken;
CREATE POLICY ucc_auth_access ON public.accounts_accounttoken FOR ALL TO ucc_auth USING (true) WITH CHECK (true);
ALTER TABLE public.accounts_auththrottle ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS ucc_auth_access ON public.accounts_auththrottle;
CREATE POLICY ucc_auth_access ON public.accounts_auththrottle FOR ALL TO ucc_auth USING (true) WITH CHECK (true);
